/**
 * @swagger
 * /api/transcript/{id}:
 *   get:
 *     summary: Get transcript by ID
 *     description: Fetch a specific transcript by its ID. Only the owner can access it.
 *     tags:
 *       - Transcripts
 *     security:
 *       - BearerAuth: []
 *     parameters:
 *       - in: path
 *         name: id
 *         required: true
 *         schema:
 *           type: string
 *         description: Transcript ID
 *     responses:
 *       200:
 *         description: Transcript retrieved
 *         content:
 *           application/json:
 *             schema:
 *               $ref: '#/components/schemas/Transcript'
 *       404:
 *         description: Transcript not found
 *   delete:
 *     summary: Delete transcript
 *     description: Permanently delete a transcript. Only the owner can delete it.
 *     tags:
 *       - Transcripts
 *     security:
 *       - BearerAuth: []
 *     parameters:
 *       - in: path
 *         name: id
 *         required: true
 *         schema:
 *           type: string
 *     responses:
 *       200:
 *         description: Transcript deleted
 *         content:
 *           application/json:
 *             schema:
 *               type: object
 *               properties:
 *                 message:
 *                   type: string
 *                   example: "Transcript deleted successfully"
 *       404:
 *         description: Transcript not found
 */

/**
 * @swagger
 * /api/transcript:
 *   post:
 *     summary: Generate video transcript
 *     description: |
 *       Generate a transcript and AI summary for a YouTube video.
 *       If a valid cached transcript exists it is reused and the cache is extended.
 *       Processing is asynchronous - poll /api/transcript/{id}/status for progress.
 *
 *       Rate limit: 5 requests per 15 minutes per IP.
 *     tags:
 *       - Transcripts
 *     security:
 *       - BearerAuth: []
 *     requestBody:
 *       required: true
 *       content:
 *         application/json:
 *           schema:
 *             type: object
 *             required:
 *               - youtubeUrl
 *             properties:
 *               youtubeUrl:
 *                 type: string
 *                 example: "https://www.youtube.com/watch?v=dQw4w9WgXcQ"
 *               language:
 *                 type: string
 *                 default: "en"
 *               summaryType:
 *                 type: string
 *                 enum: [brief, detailed, keyPoints]
 *                 default: "brief"
 *     responses:
 *       202:
 *         description: Processing started
 *         content:
 *           application/json:
 *             schema:
 *               type: object
 *               properties:
 *                 message:
 *                   type: string
 *                 transcriptId:
 *                   type: string
 *                 status:
 *                   type: string
 *                   example: "processing"
 *       400:
 *         description: Invalid YouTube URL
 *       429:
 *         description: Rate limit exceeded
 */

/**
 * @swagger
 * /api/transcript/regenerate-summary:
 *   post:
 *     summary: Regenerate transcript summary
 *     description: Regenerate an AI summary for existing transcript segments with a different summary type.
 *     tags:
 *       - Transcripts
 *     security:
 *       - BearerAuth: []
 *     requestBody:
 *       required: true
 *       content:
 *         application/json:
 *           schema:
 *             type: object
 *             required:
 *               - segments
 *               - summaryType
 *             properties:
 *               segments:
 *                 type: array
 *                 description: Transcript segments array
 *                 items:
 *                   type: object
 *               summaryType:
 *                 type: string
 *                 enum: [brief, detailed, keyPoints]
 *               language:
 *                 type: string
 *                 default: "en"
 *               videoInfo:
 *                 type: object
 *                 nullable: true
 *               hasActualCaptions:
 *                 type: boolean
 *                 default: false
 *               videoId:
 *                 type: string
 *                 nullable: true
 *     responses:
 *       200:
 *         description: Summary regenerated
 *         content:
 *           application/json:
 *             schema:
 *               type: object
 *               properties:
 *                 summary:
 *                   type: object
 *                   nullable: true
 *                 summaryError:
 *                   type: string
 *                   nullable: true
 */

