/**
 * @swagger
 * /api/video-qa/ask:
 *   post:
 *     summary: Ask a question about a video
 *     description: |
 *       Ask an AI-powered question about a YouTube video's content.
 *
 *       Question types:
 *       - standard: Mistral AI with Pinecone RAG transcript context (3/day free)
 *       - premium: Gemini multimodal with direct video analysis (2/day free)
 *
 *       Images: Up to 2 base64-encoded images per question (premium/pixtral only).
 *       reCAPTCHA token required once per hour when RECAPTCHA_SECRET_KEY is set.
 *       Rate limit: 10 requests per minute.
 *     tags:
 *       - Video Q&A
 *     security:
 *       - BearerAuth: []
 *     requestBody:
 *       required: true
 *       content:
 *         application/json:
 *           schema:
 *             type: object
 *             required:
 *               - videoId
 *               - videoUrl
 *               - sessionId
 *               - question
 *               - questionType
 *             properties:
 *               videoId:
 *                 type: string
 *               videoUrl:
 *                 type: string
 *               sessionId:
 *                 type: string
 *               question:
 *                 type: string
 *                 maxLength: 500
 *                 example: "What are the main topics discussed?"
 *               questionType:
 *                 type: string
 *                 enum: [standard, premium]
 *               images:
 *                 type: array
 *                 items:
 *                   type: string
 *                 maxItems: 2
 *                 description: Base64 data URLs (data:image/...)
 *               recaptchaToken:
 *                 type: string
 *     responses:
 *       200:
 *         description: Answer generated
 *         content:
 *           application/json:
 *             schema:
 *               type: object
 *               properties:
 *                 answer:
 *                   type: string
 *                 responseType:
 *                   type: string
 *                 tokensUsed:
 *                   type: number
 *                 fallbackUsed:
 *                   type: boolean
 *                 usage:
 *                   type: object
 *                   properties:
 *                     premiumRemaining:
 *                       type: integer
 *                     standardRemaining:
 *                       type: integer
 *                     imagesRemaining:
 *                       type: integer
 *       400:
 *         description: Missing fields or reCAPTCHA failed
 *       429:
 *         description: Daily limit reached
 */

/**
 * @swagger
 * /api/video-qa/ask/stream:
 *   post:
 *     summary: Ask a question with SSE streaming
 *     description: |
 *       Same contract as /api/video-qa/ask but returns the answer as a Server-Sent Events stream.
 *
 *       SSE event types:
 *       - chunk: incremental text token
 *       - done: final metadata including usage stats
 *       - error: error message
 *
 *       Rate limit: 10 requests per minute.
 *     tags:
 *       - Video Q&A
 *     security:
 *       - BearerAuth: []
 *     requestBody:
 *       required: true
 *       content:
 *         application/json:
 *           schema:
 *             type: object
 *             required:
 *               - videoId
 *               - videoUrl
 *               - sessionId
 *               - question
 *               - questionType
 *             properties:
 *               videoId:
 *                 type: string
 *               videoUrl:
 *                 type: string
 *               sessionId:
 *                 type: string
 *               question:
 *                 type: string
 *               questionType:
 *                 type: string
 *                 enum: [standard, premium]
 *               images:
 *                 type: array
 *                 items:
 *                   type: string
 *               recaptchaToken:
 *                 type: string
 *     responses:
 *       200:
 *         description: SSE token stream
 *         content:
 *           text/event-stream:
 *             schema:
 *               type: string
 *       429:
 *         description: Daily limit reached
 */

